update content_bodies set title = '【石川 恋】福井県坂井市へ1泊2日の旅＜旅色＞180秒ver', description = '▼旅のルートはこちらから　https://is.gd/qLns0W
福井の坂井市は、ゴツゴツした岸壁から海を望む東尋坊、明智光秀ゆかりの称念寺、市民から「お天守」と愛される丸岡城など見どころたくさん。
もちろん、冬の味覚の王様・越前がにをはじめとしたおいしい味にも出会えます。
1泊2日でちょうどいい坂井市の旅を、石川恋さんがナビゲートしてくれます。
Sakai City, Fukui Prefecture, Japan

#国内旅行　#石川恋　#旅色　#旅ログ

▼もっとコンパクトに坂井市の旅を知りたい方は60ver.へ！
https://youtu.be/hlX6d4ouRB8
▼さらにギュッと坂井市の旅を見たい方は15ver.へ！
https://youtu.be/1o-XjI7t9Sg

▼石川恋
1993年、栃木県生まれ。書籍『学年ビリのギャルが1年で偏差値を40上げて慶應大学に現役合格した話』（KADOKAWA）の表紙モデルとして注目を集める。以降、女優、『CanCam』の専属モデルとして活躍。2021年3月スタートのドラマ『やっぱりおしい刑事』（NHKBSプレミアム）では、風間俊介演じる主人公の同僚刑事を演じる。' where id = 'PngCC4938nGllMiEDRQIS';
update content_bodies set title = '[Koi Ishikawa] A 1-Night, 2-Day Trip to Sakai City, Fukui Prefecture <Tabi-iro> 180-Second Version', description = '▼You can find the travel route here: https://is.gd/qLns0W
Sakai City in Fukui is full of attractions, including the rugged cliffs overlooking the sea at Tojinbo, Shonenji Temple associated with Akechi Mitsuhide, and Maruoka Castle, affectionately known as ''Oten-shu'' by the locals.
Of course, you can also enjoy delicious flavors, including the king of winter delicacies, Echizen crab.
Koi Ishikawa will guide you through a perfectly timed trip to Sakai City over 1 night and 2 days.
Sakai City, Fukui Prefecture, Japan

#DomesticTravel #KoiIshikawa #Tabi-iro #TravelLog

▼If you want to know more compactly about the trip to Sakai City, check out the 60-second version!
https://youtu.be/hlX6d4ouRB8
▼If you want to see an even more condensed version of the trip to Sakai City, check out the 15-second version!
https://youtu.be/1o-XjI7t9Sg

▼Koi Ishikawa
Born in 1993 in Tochigi Prefecture. She gained attention as the cover model for the book ''The Story of a Gal Who Raised Her Academic Score by 40 Points in a Year and Passed Keio University'' (KADOKAWA). Since then, she has been active as an actress and a model for ''CanCam''. In the drama ''Yappari Oshiin Keiji'' (NHK BS Premium) that started in March 2021, she plays a fellow detective of the protagonist, portrayed by Shunsuke Kazama.' where id = 'x_pEtQg_ffXvWTI1au53K';
