update content_bodies set title = '奈緒｜おいしい十勝アドレス【旅色Movie】', description = '日本有数の農業・酪農地帯として知られる北海道・十勝エリア。19市町村からなるこの地域だけでの、食料自給率は、約1,100％を誇ります。食材の宝庫だけに、旅は絶品グルメの出会いとの連続。おいしいものに目がない奈緒さんが十勝のまちを巡り、大地の恵みを満喫しました。

┈┈奈緒 Profile┈┈
1995年2月10日生まれ、福岡県出身。NHK連続テレビ小説『半分、青い。』に出演し、ヒロインの親友役として注目を集め、『あなたの番です』（日本テレビ系）の怪演で話題に。以降、映画『余命10年』『マイ・ブロークン・マリコ』、ドラマ『ファーストペンギン！』など数々の話題作に出演。2023年エランドール賞新人賞、第116回ザテレビジョンドラマアカデミー賞主演女優賞を受賞後も、ドラマや映画、舞台など多方面で活躍中。

