update content_bodies set title = 'Nao | Delicious Tokachi Address【Tabiiro Movie】', description = 'The Tokachi area in Hokkaido is known as one of Japan''s leading agricultural and dairy farming regions. This area, consisting of 19 cities and towns, boasts a food self-sufficiency rate of approximately 1,100%. As a treasure trove of ingredients, the journey is filled with encounters of exquisite gourmet food. Nao, who has a keen eye for delicious food, toured the towns of Tokachi and enjoyed the blessings of the land.

┈┈Nao Profile┈┈
Born on February 10, 1995, from Fukuoka Prefecture. She gained attention for her role as the heroine''s best friend in the NHK morning drama ''Hanbun, Aoi.'' She became a topic of discussion for her remarkable performance in ''Anata no Ban desu'' (Nippon Television). Since then, she has appeared in numerous notable works, including the films ''Yomei 10-nen'' and ''My Broken Mariko,'' as well as the drama ''First Penguin!'' After receiving the 2023 Elan d''Or Award for Best Newcomer and the 116th Television Drama Academy Award for Best Actress, she continues to be active in dramas, films, and theater.

