update content_bodies set title = 'ゴルフを楽しもう、鳥羽市を楽しもう。', description = '伊勢志摩でゴルフをお楽しみください。どのゴルフ場にもアクセスが便利な鳥羽市での宿泊をお勧めします。また、さまざまな宿泊施設もご用意しています。

ゴルフの後は、ミキモト真珠島、鳥羽水族館、鳥羽ベイクルーズ、海女小屋、海の博物館など、たくさんのアミューズメントスポットがあります。

伊勢志摩でゴルフをお楽しみの皆さま。
どのゴルフ場にもアクセスが便利な鳥羽での宿泊をご案内いたします。アフターゴルフはミキモト真珠島、鳥羽水族館、鳥羽ベイクルーズ、海女小屋、海の博物館など、観光施設も充実しております。ゴルフも、お宿も、観光も、グルメも、ぜ～んぶ鳥羽で決まり。' where id = 'zCYCdZ4HNmRKTygkWr2JU';
