Historically and geographically, Eastern Hokkaido is a unique place that, while being part of Japan, is located on the North American Plate, resulting in a rich variety of rare plant species. This land is home to rare wildlife that can only be encountered here, and the many creatures that inhabit Japan''s national parks have been preserved by the local people who have coexisted with nature for generations, creating a place where ''nature remains untouched (Untouched Hokkaido)''. Eastern Hokkaido is connected by rich clear streams, and is home to the elegant and beautiful red-crowned crane, which is also a special natural monument of Japan. In the language of the Ainu, the indigenous people of Hokkaido, the red-crowned crane is called Sarorunkamuy (the god that lives in the marshlands). Water nurtures life while magically transforming into various forms.' where id = 'ETdyT3HpdC_HUPJK3VtUg';
