update content_bodies set title = '【TEASER】360°で観る飛び地の村「北山村」/VR experience for the enclave village Kitayama, WAKAYAMA.', description = '紀伊半島の秘境の飛び地村　和歌山県「北山村」。
史上初！筏師の目線で360°見渡せる北山川観光筏下りを映像化しました。

また美しい村の風景や、じゃばらの香りまで届くような収穫の様子にと奥深い秘境の景色をお楽しみいただけます。

本編は日本語、英語、中国語（繁体字）それぞれをチャンネル内に用意しています。

ーーーーーーーーーーーーーーーーーーーーーーーーーーーーーーー
The enclave village in the Kii Peninsula – Kitayama Village, WAKAYAMA.
For the first time ever, VR experience Ikada-Kudari, the Kitayama River Log Rafting from the unique perspective of a Ikada-shi, raft master with a fully immersive 360° view!

Enjoy the breathtaking scenery of this secluded village and its picturesque landscapes, and feel as if the refreshing citrus aroma of the Jabara harvest is drifting through the screen."

The full video is available in Japanese, English, and Traditional Chinese on this channel!' where id = 'o6bL67IrRpj0O26bntVB_';
update content_bodies set title = '【TEASER】360°で観る飛び地の村「北山村」/VR experience for the enclave village Kitayama, WAKAYAMA.', description = 'The enclave village in the Kii Peninsula – Kitayama Village, WAKAYAMA.
