update content_bodies set title = 'こんな田舎なのに魅力たっぷりえびの市。知らなかった人損してますよ。', description = 'こんにちは！宮崎県えびの市観光商工課ＰＲ担当のみなほです。
皆さんえびの市を知っていますか？
ポテンシャルは高いのに中々知名度が上がらないこの町。
観光地や綺麗な景色、特産品もあるのに知ってもらえないこの町。
そんなポテンシャル満載の魅力たっぷりなこの町をもっと色んな人に知ってもらいたい、従来の情報発信だけでは伝わらないこのご時世。
そこで、みなほ、動画配信始めます。

新型コロナウイルス感染症によりアウトドア人気が高まった時、えびの高原にある「えびの高原キャンプ村」が大盛り上がりしたのは地元の人しか知らない…。

今回の動画で紹介するえびの高原はキャンプやトレッキングするには最適の場所。
えびの高原の四季折々の景色に囲まれて体験するアウトドアアクティビティは非日常感にあふれていて、仕事や私生活のストレスを発散するには最高のデトックス効果抜群の場所です！

この動画を見て少しでも魅力を感じたそこのあなた！

えびの市は皆さんを迎える準備はいつでも出来ていますよ！

是非、えびの市へおじゃったもんせ（お越しください）~！


【今回の動画に登場した観光施設】
道の駅えびの　https://michinoeki-ebino.com/
えびの高原屋外アイススケート場　https://ebinokogenso.com/skate/
えびの高原キャンプ村　https://ebino-village.com/
白鳥温泉下湯　http://shiratori-onsen.com/wp/down/

【えびの市観光サイト】
https://www.city.ebino.lg.jp/kanko/index.html' where id = 'XifZ6hghebGxhAdXEyccC';
update content_bodies set title = 'Ebino City, full of charm despite being in the countryside. Those who didn''t know are missing out.', description = 'Hello! I''m Minaho, the PR representative of the Tourism and Commerce Division of Ebino City, Miyazaki Prefecture.
Do you know about Ebino City?
This town has high potential but struggles to gain recognition.
Despite having tourist attractions, beautiful scenery, and local specialties, this town remains unknown.
I want more people to know about this town, which is full of potential and charm, especially in this day and age where traditional information dissemination isn''t enough.
So, I, Minaho, will start video streaming.

When the popularity of outdoor activities surged due to the COVID-19 pandemic, the "Ebino Kogen Camp Village" in Ebino Kogen became a huge hit, known only to locals...

The Ebino Kogen introduced in this video is the perfect place for camping and trekking.
Experiencing outdoor activities surrounded by the seasonal scenery of Ebino Kogen is filled with a sense of the extraordinary, making it an excellent detox spot to relieve stress from work and personal life!

If you feel even a little charm from watching this video, you!

Ebino City is always ready to welcome you!

Please come to Ebino City~!

