update content_bodies set title = '平湯大滝  冬　氷の世界　Hida Hirayu waterfall in winter      岐阜県 高山市 奥飛騨温泉郷', description = '岐阜県高山市奥飛騨温泉郷にある落差64メートル、幅6メートルの平湯大滝は飛騨三大名瀑のひとつで、日本の滝百選にも選定されている「平湯大滝」巨大な滝の流れはこの冬の時期と共に氷結しまるで行く手を阻むかの如く氷の柱と姿を変えます。自然の力がなす氷の彫刻をどうぞ、ご堪能ください。

Hirayu Otaki, located in Okuhida Onsengo, Takayama City, Gifu Prefecture, has a height of 64 meters and a width of 6 meters. With the winter season, it freezes and transforms into a pillar of ice as if it were blocking the way. Please enjoy the ice sculpture created by the power of nature.' where id = 'fUc1UDOFZHh9dGJb-o2d0';
update content_bodies set title = 'Hida Hirayu waterfall in winter', description = 'Hirayu Otaki, located in Okuhida Onsengo, Takayama City, Gifu Prefecture, has a height of 64 meters and a width of 6 meters. It is one of the three great waterfalls of Hida and has been selected as one of Japan''s top 100 waterfalls. During the winter season, the massive flow of the waterfall freezes, transforming into pillars of ice as if blocking the way. Please enjoy the ice sculpture created by the power of nature.' where id = 'YyQckYfFBwL266_ow8V84';
update content_bodies set title = '熊野神社 伊邪那美(イザナミ)の道 - KUMANO Shrine The road of IZANAMI', description = '広島県庄原市、熊野神社。旧比婆大社。創建年は不詳。比婆山山麓に位置するこの場所は日本最古とされる歴史書『古事記』の伝承を現代に伝える場所です。
神々の母伊邪那美命(イザナミノミコト)は、立烏帽子山に伊邪那岐(イザナギノミコト)が訪ねてきた際、夜になったので自分の櫛に火をつけて灯りとして、この山道を歩き、天から火の雨が降り注いだ際に途中の岩穴に身を隠し難を逃れたという逸話が残されています。
また、後に火の神を産んだ伊邪那美は、この道の岩穴で亡くなり、黄泉の国に旅立ったとも伝えられています。

Kumano Shrine, Shobara City, Hiroshima Prefecture.  Former Hiba Ohyashiro Shrine.  The year of foundation is unknown.  Located at the foot of Mt. Hiba, this place is a place to convey the tradition of Japan''s history book said that oldest history book "Kojiki" to the present day.
 The mother of the gods, Izanami Nomikoto When Izanagi Nomikoto visited her, Mt. Tateeboshi, It''s night, so she lit her comb and used it as a light. There is an anecdote that she hid herself in a rock hole on the way and escaped the difficulty when it rained on fire from the sky.
 It is also reported that Izanami, who later gave birth to the god of fire, died in a rock hole on this road, and she left for heaven.

