update content_bodies set title = '出雲大社 - IZUMO NO OHYASHIRO', description = '出雲大社 - IZUMO NO OHYASIRO
出雲大社(いずものおおやしろ・いずもたいしゃ)は島根県出雲市大社町杵築東にある神社です。
日本最古の神社の一つで、主祭神である大国主大神(オオクニヌシノオオカミ)は日本国創造の神様とされています。旧暦の十月には八百万の神(やおよろずのかみ)がこの地に集まり、神議(神様の会議)が行われると言い伝えられてきました。

