Izumo Taisha is a shrine located in Kizukihigashi, Taisha-cho, Izumo City, Shimane Prefecture.
 One of the oldest shrines in Japan, Okuninushi no Okami, the main deity, is considered to be the god who created Japan.  It has been said that in October of the lunar calendar, eight million gods (Yaorozu no Kami) will gather here and hold a deity (God''s meeting).

