update content_bodies set title = 'しまなみ海道　全長54km　瀬戸内の多島美！VRの旅　Shimanami Sea load,  beauty of scattered islands in Setouchi! VR trip', description = '瀬戸内海は本州と四国の間に広がる内海で、大小約700余に及ぶ島々が点在しています。
本州の尾道(広島県)〜今治(愛媛県)をつなぐ連絡道路は3ルートあり、そのうちの一つにしまなみ海道(西瀬戸自動車道)があります。
尾道から向島、因島、生口島、大三島、伯方島、大島、そして今治まで全長54kmに及ぶ風光明媚な街道です。
瀬戸内海の多島美と、しまなみ海道の壮大な景色をVRでお楽しみください。

The Seto Inland Sea is an inland sea that stretches between Honshu and Shikoku, and is dotted with about 700 large and small islands.
There are 3 roads connecting Onomichi (Hiroshima Prefecture) and Imabari (Ehime Prefecture) in Honshu, one of them is the Shimanami Kaido (Nishi Seto Expressway).
It is a scenic road that stretches 54km from Onomichi to Mukaishima, Innoshima, Ikuchijima, Omishima, Hakatajima, Oshima, and Imabari.
Please enjoy the beauty of scattered islands in Setouchi and  magnificent view of Shimanami Kaido in VR.

