update content_bodies set title = '【Yamagata - Tohoku / Japan travel】K-hour ‐spring‐', description = '「K-hour movie」春編を公開します。

「K-hour」では金山にある“暮らし”や“日常”を切り取り、
金山を訪れる時には同じ日常をみていただくために動画を製作しました。

金山町には金山にしかないであろう時間が流れています。 それは穏やかでゆっくりした、訪れる人をあたたかくつつみ込むようなときの流れ。
澄んだ空気に触れ、山の匂いを感じ、溢れる笑顔が自然とある。 営みに寄り添うように日が暮れ、一日を照らし出すようにまた日が昇る。 心をありのままに過ごす時間。 

短い金山の春のひと時、金山を訪れた二人が撮った「金山でうまれる、私たちの時間。」を感じてみてください。 

主宰：山形県金山町
統括プロデューサー：吉野敏充
プロデューサー：渡辺然
監督／演出：佐藤鈴華
撮影：布施果歩・佐藤明日翔
編集：佐藤鈴華
主演：阿部優奈・國井優希
制作：Strobelight

