update content_bodies set title = '[Yamagata - Tohoku / Japan travel] K-hour -spring-', description = 'We are releasing the spring edition of the ''K-hour movie''.

In ''K-hour'', we capture the ''lifestyle'' and ''everyday life'' in Kaneyama,
creating videos so that visitors can see the same daily life when they come to Kaneyama.

In Kaneyama, there flows a time that can only be found here. It is a gentle and slow passage of time that warmly envelops those who visit.
Touching the clear air, feeling the scent of the mountains, and smiles overflowing naturally. As the day fades, it embraces the activities of the day, and again the sun rises to illuminate the day. Time spent with an open heart.

Experience the short moment of spring in Kaneyama, captured by two visitors in ''Our time born in Kaneyama.''

Organizer: Kaneyama Town, Yamagata Prefecture
Executive Producer: Toshimitsu Yoshino
Producer: Zen Watanabe
Director/Production: Suzuka Sato
Cinematography: Kaho Fuse, Asuto Sato
Editing: Suzuka Sato
Starring: Yuna Abe, Yuki Kunii
Production: Strobelight

