update content_bodies set title = '【Yamagata - Tohoku / Japan travel】K-hour ‐community-reactivating cooperator squad‐', description = '「K-hour movie」地域おこし協力隊編を公開します。

 「K-hour project」では金山にある“暮らし”や“日常”を切り取り、 金山を訪れる方に金山の日常をみて感じていただくため動画を製作しています。 

昨年、金山町に本間真生さんが地域おこし協力隊として着任しました。現在、町外の方々と新たな関係性を結ぶ取組みや金山町のファンを作るために様々な活動しています。

今回の動画では、地域おこし協力隊として金山で暮らし、働くなかでできた繋がり。
地元ではないけれど、地元以上に地元のように思い感じ暮らし歩んでいく。
金山町と彼女の関わりから生まれている「金山の時間」を感じてみてください。 

