update content_bodies set title = '2泊3日で周遊！岡山を味わい尽くす女子二人旅', description = 'みなさんは、岡山県の魅力をどのくらい知っているでしょうか。
古き良き街並みを堪能できる「倉敷」を思い出す人が多いのでは？　でもそれだけじゃないんです！

大自然と広大な高原で気分をリフレッシュできる「蒜山（ひるぜん）高原」や歴史ある温泉街「湯原温泉」、恋人たちの聖地と言われる「黒島ヴィーナスロード」などなど…
挙げたらキリのない岡山県の魅力の数々を、2泊3日で味わい尽くす女子二人旅にまとめました！

