update content_bodies set title = '美宙　 岡山県備中、星と宙を巡る旅　☆彡', description = '「晴れの国」と呼ばれる岡山県は、晴天率の高さに加え大気が安定しているため、星の光の揺らぎが少なく、天体観測に適していると言われています。なかでも天文施設やキャンプ場など、夜に訪れたい人気スポットが集まっている「備中エリア」。美しく光る満天の星と宙（そら）を眺めながら、備中エリアを巡ってみませんか。

▼「カラフル備中」公式Instagram
https://www.instagram.com/colorfulbichu/

▼備中地域の観光情報が盛りだくさん！「ＣＯＬＯＲＦＵＬ　ＢＩＣＨＵ　カラフル備中」ＷＥＢサイトもチェック！
http://www.bichu-okayama.jp/' where id = 'hFyZ_EACTCrbbGsm7pzTr';
update content_bodies set title = 'Bichu: A Journey Through Stars and the Sky in Okayama Prefecture ☆彡', description = 'Okayama Prefecture, known as the ''Land of Sunshine,'' is said to be suitable for stargazing due to its high rate of clear weather and stable atmosphere, which results in minimal twinkling of stars. Among these, the ''Bichu Area'' is home to popular spots like astronomical facilities and campgrounds that are perfect for night visits. Why not explore the Bichu Area while gazing at the beautifully shining stars and sky?

▼ Official Instagram of ''Colorful Bichu''
https://www.instagram.com/colorfulbichu/

▼ Check out the ''COLORFUL BICHIU'' website for plenty of tourist information about the Bichu region!
http://www.bichu-okayama.jp/' where id = 'yb3IYy0LazXBM4B8dP_YX';
