update content_bodies set title = '【English Ver.】TAMANO Calling ～玉野があなたを呼んでいる～　岡山県玉野市PR動画（240s）', description = '"A city where travelers want to live"
The Setouchi Triennale was held, and now "Setouchi" is aimed at travelers from all over the world.
This is Tamano, a port town where travelers "pass by" as a gateway to the islands.
During the "passing", there are people who were fascinated by this city and decided to live in this city.
Yes, let''s ask them.
The charm of this city that captures the hearts of travelers.

Introducing the voices of people who have moved to this city.

