update content_bodies set title = '自転車の街たまのＰＲ動画　3分／完全版', description = '玉野市観光大使 渚さんや、吉本芸人で「岡山県住みます芸人」の江西あきよしさん、ハロー植田さん、ネゴシックスさんと玉野高校の生徒がコラボして制作したサイクリングＰＲ動画です。

高校生が玉野の日常生活の中で好きな場所や店舗を渚さんにＰＲして、共同で市内を周遊す
るサイクリングコースをつくりました。
実際に渚さんがサイクリングで巡っています。

海岸沿いや田園風景、素敵なお店など、市内の魅力的なスポットをたくさん見ることが
でき、玉野市をサイクリングしたくなる動画になっています。ぜひご覧ください。

A cycling PR video created in collaboration with Tamano City tourism ambassador Nagisa
and other Yoshimoto comedians and Tamano High School students has been completed.
The high school students told Nagisa about their favorite places and stores in their daily
lives, and together they created a cycling course around the city.
This video shows Nagisa actually cycling on a cycling course.
You can see many attractive spots in the city, such as the coastline, rural scenery, and
wonderful shops, making it a video that will make you want to cycle around Tamano City.
Please take a look.

#岡山県玉野市 #玉野市 #PR ＃玉野市観光大使 ＃渚 ＃吉本興業 ＃江西あきよし
