update content_bodies set title = 'PR Video of the Cycling City Tamano - 3 Minutes / Complete Version', description = 'This is a cycling PR video created in collaboration with Tamano City tourism ambassador Nagisa, Yoshimoto comedians Akiyoshi Kawai, Hello Ueda, Negosix, and students from Tamano High School.

The high school students promoted their favorite places and stores in their daily lives to Nagisa, and together they created a cycling course around the city.
Nagisa is shown actually cycling on this course.

You can see many attractive spots in the city, such as the coastline, rural scenery, and wonderful shops, making it a video that will make you want to cycle around Tamano City. Please take a look.

