update content_bodies set title = '瀬戸内国際芸術祭 2019（SETOUCHI TRIENNALE） in 宇野港周辺【総集編】', description = '瀬戸内国際芸術祭2019 宇野港周辺会場で春・夏・秋会期にわたり、展示された作品やイベントを紹介しています。
Introducing works and events that were exhibited at SETOUCHI TRIENNALE 2019 at the venues around Uno Port during the spring, summer and autumn seasons.

オープニングイベント（2019/4/27）
山地真美氏によるピアノ演奏や市内高校吹奏楽部との合同演奏など実施

