update content_bodies set title = 'Hokkaido’s Niagara Falls', description = '北海道にあるナイアガラの滝（伊達市大滝区）と言われるこの滝は、大滝総合運動公園から、長流川沿いの森林を歩く約６㎞のトレイルコ
ースニアル。落差３ｍ、幅３０ｍの大滝ナイアガラの滝や徳舜瞥山の眺望が楽しめる。' where id = 'tWY-p8bayxPA-VR0RhlaQ';
update content_bodies set title = 'Hokkaido’s Niagara Falls', description = 'This waterfall, known as Niagara Falls in Hokkaido (in the Otaki area of Date City), is accessible via a trail course of about 6 km along the Nagauru River through the forest from the Otaki General Sports Park. You can enjoy the view of the 3-meter drop and 30-meter width of the Otaki Niagara Falls, as well as the scenery of Mount Tokushunbetsu.' where id = '41IptfvSEmjWPAR_HAhTE';
update content_bodies set title = 'Active Volcano Walk  - Summit of Mt.Usu -', description = '活火山を歩く。
有珠山外輪山からは、火口原内部にそびえる小有珠、大有珠、オガリ山、有珠新山などの溶岩ドームが見える。

Active Volcano Walk (Summit of Mt. Usu)
A walk around the out rim of Mt. Usu grants a view of Mt. Ko-usu towering out of the crater, and the surrounding volcanic formations such as Mt. Ogari, Mt. Ō-usu and the Usushinzan lava dome.' where id = 'fRrh02zIXhcDJdN-2gs--';
update content_bodies set title = 'Active Volcano Walk - Summit of Mt. Usu -', description = 'A walk around the active volcano.
From the outer rim of Mt. Usu, you can see the lava domes of Ko-usu, Ō-usu, Mt. Ogari, and Usushinzan towering within the crater.' where id = 'fy-ndub-Ot4XiRrle6Jmf';
update content_bodies set title = 'The Scar Left Behind (金比羅火口災害遺構散策路)', description = '金比羅火口災害遺構散策路では、2000年噴火で形成された火口や、熱泥流などの災害で被災した施設など、学びの場として災害遺構を見学することができます。

是非、ご覧いただければと思います。

CORRECTION: The trail was destroyed by a mudslide, not by lava.' where id = 'wahIBJzy6kdCBzKJ_yOCr';
update content_bodies set title = 'The Scar Left Behind (金比羅火口災害遺構散策路)', description = 'At the Konpira Crater Disaster Ruins Trail, you can visit disaster ruins as a place of learning, including the crater formed by the eruption in 2000 and facilities affected by disasters such as hot mud flows.

We hope you will take a look.

CORRECTION: The trail was destroyed by a mudslide, not by lava.' where id = 'qERNXU6x4DJTqqKqztW3S';
update content_bodies set title = 'Hokkaido fisherman in spring', description = '北海道の内浦湾にある洞爺湖町では、ホタテの養殖が盛んだ。
ユネスコの世界遺産にも登録されているこの地域は、100年の間に４度も噴火を繰り返す「有珠山」や、噴火によって形成されたカルデラ湖「洞爺湖」があり、その噴火によって降り注ぐ火山灰はやがて豊富な土壌となり、川からはミネラル豊富な水が海に注がれる。
そんな美しい海で育ったホタテの味は絶品である。

特に春は、「耳づり」と言われる独特な養殖方法に多くの人手が必要なため、小さな漁業町は活気づく季節である。' where id = 'Ogn9pYpGqmXURqswhI6n4';
update content_bodies set title = 'Hokkaido fisherman in spring', description = 'In Toyako Town, located in Uchiura Bay, Hokkaido, scallop farming is thriving.
This region, which is registered as a UNESCO World Heritage site, features Mount Usu, which has erupted four times over the past 100 years, and Lake Toya, a caldera lake formed by volcanic eruptions. The volcanic ash that falls from these eruptions eventually becomes rich soil, and mineral-rich water flows from the rivers into the sea.
The taste of scallops raised in such beautiful waters is exquisite.

Especially in spring, the unique farming method known as ''mimizuri'' requires a lot of manpower, making this small fishing town a bustling place during the season.' where id = 'n-ta__AGZdj7N0cAB1Cfi';
update content_bodies set title = '埼玉県熊谷市グルメCMシリーズ『雪くま編』', description = '埼玉県熊谷市グルメCMシリーズ『雪くま編』です。

荒川が関東平野に流れ込む扇状地に広がる熊谷市は、伏流水による美味しい地下水が豊富で、その美味しい熊谷の水をつかった氷を、ふわふわに仕上げたかき氷が『雪くま』です。
日本一の夏の暑さが、かき氷をさらに美味しくしてくれます。

https://www.oideyo-kumagaya.com/cate-gourmet/361/' where id = 'AHrw3dpYHaE58-aokKXuL';
update content_bodies set title = 'Kumagaya City Gourmet CM Series ''Yuki Kuma Edition''', description = 'This is the Kumagaya City Gourmet CM Series ''Yuki Kuma Edition''.

Kumagaya City, which spreads across the fan-shaped alluvial plain where the Arakawa River flows into the Kanto Plain, is rich in delicious underground water from spring water. The fluffy shaved ice made with this delicious Kumagaya water is called ''Yuki Kuma''.
The hottest summer in Japan makes the shaved ice even more delicious.

https://www.oideyo-kumagaya.com/cate-gourmet/361/' where id = 'BVmhEblO8S7DHzHIPxfdm';
