update content_bodies set title = '北海道釧路阿寒湖アイヌ文化ガイドツアー「刺繍の時間」～Anytime Ainutaimu（エニタイムアイヌタイム）　アイヌとともに時間を過ごす阿寒湖旅～', description = 'ツアー公式HP
https://anytimeainutime.jp/

日本の先住民族「アイヌ」。
阿寒湖のほとりに今も息づく彼らの文化を、現代に生きるみなさまに。

古くからアイヌと和人とが協働してきた阿寒湖のアイヌ文化は、
他の地域にはない特色を持っています。
北海道最大規模のアイヌコタン（集落）があり、工芸品販売や歌、踊りなどの
文化が脈々と受け継がれている地域が阿寒湖なのです。' where id = 'YEF1icxUx7LbyELX8wyiM';
update content_bodies set title = 'Ainu Cultural Guide Tour at Lake Akan, Hokkaido "Embroidery Time" ~ Anytime Ainutaimu - A Journey at Lake Akan Spending Time with the Ainu ~', description = 'Official tour website
https://anytimeainutime.jp/

Japan''s indigenous people, the Ainu.
Their culture, which still thrives by the shores of Lake Akan, is for everyone living in the modern world.

The Ainu culture at Lake Akan, where the Ainu and the Wajin have collaborated for a long time, has unique characteristics not found in other regions.
Lake Akan is home to the largest Ainu village in Hokkaido, where crafts, songs, dances, and other cultural traditions are continuously passed down.' where id = 'wXW6Jzo3y9IinpuuWlrmS';
