update content_bodies set title = 'EN（縁）', description = '若狭湾と若狭富士「青葉山」に囲まれる福井県高浜町は、鈴木大拙の師にして世界へ禅をZENとして初めて広めたパイオニアである釈宗演の生誕の地です。
釈宗演が幼少期を過ごした海と山に囲まれた若狭高浜。自然とつながり、人とつながり、心と体をリセットするZEN（禅、然、膳、善、全…）の体験が、今も暮らしの中に息づいています。
陰陽の陽（春夏）を表現した今回の動画では、ZENのEN（縁）に出会ってほしいという思いを込めました。

縁がつながり、新たな縁を紡いでいく。

そんな高浜へ、ZENの体験を、日本海の美味しい魚を味わいに、そしてワーケーションをしに、福井県高浜町へお越しください。

🔵高浜町ワーケーションHP
⇒https://wakasa-takahama.jp/workation/
 
🔵ワーケーション  タブロイド紙
⇒http://www.town.takahama.fukui.jp/pag...

 
