update content_bodies set title = '[Takahama Town, Fukui Prefecture] Otomi Cliff', description = 'A spectacular cliff designated as a scenic spot of the prefecture, reaching a height of 260 meters. There is a walking path that continues to the Oshi-mae Lighthouse, where you can enjoy part of the great cliff along the way.

