update content_bodies set title = '【福井県高浜町】えびす浜パーク海水浴場－Ebisuhama Park Beach', description = '広い階段になっているので砂が少なくて休みやすいビーチです。磯遊びができる岩場があり、ほどよい広さのビーチなので、小さいお子様連れにもおすすめです。海水浴期間中のみ、砂浜全域でBBQが可能なのも魅力のひとつです。

