update content_bodies set title = '[Takahama Town, Fukui Prefecture] Ebisuhama Park Beach', description = 'This beach has wide steps, making it easy to relax with less sand. There are rocky areas for tide pooling, and the beach is of a suitable size, making it recommended for families with small children. One of the attractions is that BBQs are allowed on the entire sandy area only during the swimming season.

Introduction to Ebisuhama Park Beach ⇛ https://wakasa-takahama.jp/spot/evishama-beach/

