update content_bodies set title = '【福井県高浜町】はまなすパーク海水浴場－Hamanasu Park Beach', description = '特に波が穏やかで、小さいお子様連れにも安心の海水浴場です。海水浴期間中のみ、砂浜全域でBBQが可能なのも魅力のひとつです。また、1,400mにわたる遊歩道もあります。

はまなすパーク海水浴場の紹介⇛https://wakasa-takahama.jp/spot/hamanasu-beach/

