update content_bodies set title = 'Hamanasu Park Beach in Takahama Town, Fukui Prefecture', description = 'This beach is particularly calm, making it safe for families with small children. One of its attractions is that BBQs are allowed on the entire sandy beach only during the swimming season. Additionally, there is a 1,400m promenade.' where id = 'j29q6wuxDoJ2ckISFhvaI';
update content_bodies set title = '【福井県高浜町】若宮海水浴場－Wakamiya Beach', description = '最近再整備された、高浜の海水浴場発祥の地です。 比較的人が少ないので、ゆっくりと海水浴を楽しみたい方にピッタリのビーチです。

