update content_bodies set title = 'Wakamiya Beach - Takahama Town, Fukui Prefecture', description = 'This is the birthplace of Takahama''s beach, recently renovated. 
It is a relatively less crowded beach, perfect for those who want to enjoy a relaxing day by the sea.' where id = 'YU_DGTXrT0SPHWWVRAooo';
update content_bodies set title = '【福井県高浜町】若狭和田ビーチ－Wakasa Wada Beach', description = '福井県高浜町の若狭和田ビーチは、アジアで初の国際環境認証「BLUE FLAG」を取得した人気のビーチで、バツグンの透明度と遠浅の海、白く広い砂浜が特徴です。日本の水浴場88選にも選ばれています。海水浴開設期間中は、水難救助員やライフセーバーが常駐しており、安心安全なビーチです。また、景観も良く、日本の夕日百選にも選ばれています。

若狭和田ビーチページ⇛https://wakasa-takahama.jp/spot/wakasawada-beach/

若狭高浜観光協会公式サイト⇛https://wakasa-takahama.jp/' where id = 'BoaVesHfNH4K7FUVkK85l';
update content_bodies set title = 'Wakasa Wada Beach in Takahama, Fukui Prefecture', description = 'Wakasa Wada Beach in Takahama, Fukui Prefecture, is a popular beach that has received the first international environmental certification "BLUE FLAG" in Asia. It is characterized by its outstanding transparency, shallow waters, and wide white sandy beach. It has also been selected as one of Japan''s 88 bathing beaches. During the swimming season, lifeguards and rescue personnel are stationed on the beach, ensuring a safe and secure environment. Additionally, the scenery is beautiful, and it has been chosen as one of Japan''s top 100 sunsets.

Wakasa Wada Beach page⇛https://wakasa-takahama.jp/spot/wakasawada-beach/

Wakasa Takahama Tourism Association official site⇛https://wakasa-takahama.jp/' where id = '9QaDF9TDKDqcTylpZjvQO';
update content_bodies set title = '【福井県高浜町】城山海水浴場－Shiroyama Beach', description = '波が少なく、磯遊びができる岩場があり、小さいお子様連れのファミリーに人気です。高浜町の景勝地「明鏡洞」のある城山公園がすぐ横にあり、芝生広場なども同時に楽しめます。城山公園は日本の夕日百選にも選ばれており、景観も楽しめます。

城山海水浴場の紹介⇛https://wakasa-takahama.jp/spot/shiroyama-beach/

若狭高浜観光協会公式サイト⇛https://wakasa-takahama.jp/' where id = 'OQAUscd3Sq6zP-m-GWyC4';
update content_bodies set title = '[Fukui Prefecture Takahama Town] Shiroyama Beach', description = 'With gentle waves and rocky areas for tide pooling, it is popular among families with small children. Shiroyama Park, which features the scenic spot ''Meikyo Cave,'' is right next door, allowing visitors to enjoy the grassy areas as well. Shiroyama Park has also been selected as one of Japan''s top 100 sunset spots, offering beautiful views.

Introduction to Shiroyama Beach ⇛ https://wakasa-takahama.jp/spot/shiroyama-beach/

Wakasa Takahama Tourism Association Official Site ⇛ https://wakasa-takahama.jp/' where id = '0HfjUOk7XMLlEf_IQKUm4';
