update content_bodies set title = '神奈川県観光プロモーション映像', description = '神奈川県では、訪日観光客の周遊・宿泊を促すため、県の外国語情報ウェブサイト - Kanagawa Travel Info - などで県内の観光地をPRするプロモーションに取り組んでいます。今回は県内のIT事業者である株式会社アイネットにご協力いただき、県内の主要観光である鎌倉、箱根、江の島、大山、小田原、大雄山をドローンで撮影し、プロモーション用映像を作成しました。' where id = 'rETHw8smiiGqaNqATbPuK';
update content_bodies set title = 'Kanagawa Prefecture Tourism Promotion Video', description = 'Kanagawa Prefecture is working on a promotion to encourage inbound tourists to explore and stay in the area by promoting local tourist attractions on the prefecture''s foreign language information website - Kanagawa Travel Info - and more. This time, we collaborated with a local IT company, Ainet Co., Ltd., to film major tourist spots in the prefecture, including Kamakura, Hakone, Enoshima, Oyama, Odawara, and Daiozan, using drones to create promotional videos.' where id = 'F42RKTEMRj3K1qzjBVwTP';
