update content_bodies set title = '瀬見温泉', description = '最上小国川の清流に臨む静かな温泉場。山水の景勝に恵まれ、特に紅葉の季節がすばらしい温泉地です。源義経の妻、北の方が亀若丸を生んだ際、産湯を探しに出た弁慶が近くの岩陰から立ち昇る湯煙を見つけたのがこの温泉の始まりと伝えられています。近くには亀若丸の誕生に加護のあった亀割子安観音や瀬見温泉の守り神が祀られている湯前神社など、義経・弁慶に関する伝説や旧跡が数多く残っています。夏は、近くを流れる最上小国川でアユ釣りを楽しむ方を多く見かけます' where id = 'qiBH-C6Kw9u2XHBiM9zs2';
update content_bodies set title = 'Semmi Onsen', description = 'A quiet hot spring resort overlooking the clear stream of the Mogami Oguni River. Blessed with scenic mountain waters, this hot spring area is particularly wonderful during the autumn foliage season. It is said that the origin of this hot spring began when Benkei, searching for a bath for Kamewakamaru, the child of Yoshitsune''s wife, Kito no Kata, discovered the rising steam from a nearby rock. Nearby, there are many legends and historical sites related to Yoshitsune and Benkei, such as the Kamewakamaru''s protective Kamewariko An Kannon and the Yumemae Shrine, which enshrines the guardian deity of Semmi Onsen. In summer, many people can be seen enjoying sweetfish fishing in the nearby Mogami Oguni River.' where id = '_g4VuP1EgmRcsUr2xwpBC';
update content_bodies set title = '【東北・山形】「EMMA」山形県最上町プロモーション動画  Promotion Video for Mogami Town, Yamagata (Tohoku, Japan)', description = '[山形県最上町の歴史や風景を背景にした心が動かされる短編物語]

　最上町は、古来より馬の産地であり、小国駒と呼ばれる名馬の産地として、馬を慈しみ深い関わりを持って暮らしてきた町であった。
　今回のプロモーション動画は、東北三大馬頭観音の一つであり、馬の守り神として崇拝されてきた富山馬頭観音の東善院と、近代では観光地として「馬」に関わりの深い前森高原をメインロケ地にし、その2箇所が『桜』の名所でもあり、『馬』と『桜』、その桜のイメージから『女性』をテーマに、主人公の過去から未来に繋がるストーリーを町の魅力的なロケ地を活かして制作。


[A moving short story set against the backdrop of the history and scenery of Mogami Town, Yamagata Prefecture]

Mogami Town has been a horse-breeding town since ancient times, and as the birthplace of the famous horse called Oguni Koma, it has been a town where people have lived in a beautiful and deep connection with horses.
The main locations for this promotional video are Tozen-in Temple of Tomiyama Bato Kannon, one of the three major horse-headed Kannon temples in the Tohoku region and worshipped as the guardian deity of horses, and Maemori Plateau, which has a deep connection with horses as a tourist destination in modern times. These two places are also famous for cherry blossoms. The story is based on the theme of horses, cherry blossoms, and the protagonist, taking advantage of the town''s attractive locations to create a story that connects the protagonist''s pas, present, and future.


***

