update content_bodies set title = 'Walk the Magose pass on the Kumano Kodo trail, UNESCO World heritage site', description = '■Activity details■
Long ago, it was popular for people from all across Japan to walk hundreds of kilometers to tour sacred sites such as Ise Grand Shrine and Kumano Sanzan (the Three Grand Shrines of Kumano). Many travelers walked the perilous Magose Pass, which is part of the Sacred Sites and Pilgrimage Routes in the Kii Mountain Range that leads to Kumano Sanzan. The beautiful stone paved path leading deep into the forest has been lovingly maintained by locals for centuries, and still looks as it did long ago. This program offers participants the chance to dress in travel garb recreated from ukiyo-e prints and historic documents and walk the Magose Past just as ancient travelers did. Partial proceeds from the program are used to preserve the stone paving and keep the scenery in pristine condition for future generations.

■コンテンツの概要＆ストーリー■
かつて日本では、日本全国から何百キロもの道のりを歩いて伊勢神宮や熊野三山を参拝する聖地巡礼の大ブームが起きました。世界遺産「紀伊山地の霊場と参詣道」の一部である「馬越峠」もまた、数多くの旅人がいくつもの険しい峠を越え、熊野三山を詣でるために通った“祈りの道”の一つ。森の奥へと伸びる美しい石畳は、何百年もの間、地元の人々の手によって大事に保全され、今もなお、当時の姿を留めています。本プログラムでは、浮世絵や文献等を参考に再現された旅装束に身を包み、かつての旅人たちのように馬越峠を歩きます。体験代の一部は、この先もこの美しい景色を残すため、石畳の保全活動費用に使われます。

■特設サイト”Exclusive Activities Information for Travel Agencies”　
＊日本語：https://www.kankomie.or.jp/special/fortravelagencies/
＊English：https://www.kankomie.or.jp/special/fortravelagencies/en/

三重県の豊かな自然の恵みや人々の生活に触れ、「三重県ならでは」の魅力を存分に感じることができる、特別な体験をご用意しました。ぜひ上記サイトより詳細をご確認ください。
We’d like to offer you exclusive experiences that will allow you to experience the rich natural bounty of Mie Prefecture and the lives of its people, and to fully appreciate the charms "unique to Mie Prefecture".
Please check the website link above for more information.' where id = 'jBYaFFzJiFuwN6TJhpqJb';
update content_bodies set title = 'Walk the Magose pass on the Kumano Kodo trail, UNESCO World heritage site', description = '■Activity details■
Long ago, it was popular for people from all across Japan to walk hundreds of kilometers to tour sacred sites such as Ise Grand Shrine and Kumano Sanzan (the Three Grand Shrines of Kumano). Many travelers walked the perilous Magose Pass, which is part of the Sacred Sites and Pilgrimage Routes in the Kii Mountain Range that leads to Kumano Sanzan. The beautiful stone paved path leading deep into the forest has been lovingly maintained by locals for centuries, and still looks as it did long ago. This program offers participants the chance to dress in travel garb recreated from ukiyo-e prints and historic documents and walk the Magose Past just as ancient travelers did. Partial proceeds from the program are used to preserve the stone paving and keep the scenery in pristine condition for future generations.

■Overview & Story of the Content■
In the past, there was a great boom in Japan where people walked hundreds of kilometers from all over the country to visit sacred sites such as Ise Grand Shrine and Kumano Sanzan. The Magose Pass, which is part of the UNESCO World Heritage Site "Sacred Sites and Pilgrimage Routes in the Kii Mountain Range," is one of the "paths of prayer" that many travelers crossed to visit the Three Grand Shrines of Kumano. The beautiful stone-paved path extending deep into the forest has been carefully preserved by local people for hundreds of years and still retains its original appearance. In this program, participants will don travel garments recreated from ukiyo-e and historical documents and walk the Magose Pass just like the ancient travelers did. A portion of the experience fee will be used for the preservation of the stone pavement to ensure that this beautiful scenery remains for future generations.

■Special Site “Exclusive Activities Information for Travel Agencies”
＊Japanese: https://www.kankomie.or.jp/special/fortravelagencies/
＊English: https://www.kankomie.or.jp/special/fortravelagencies/en/

We’d like to offer you exclusive experiences that will allow you to experience the rich natural bounty of Mie Prefecture and the lives of its people, and to fully appreciate the charms "unique to Mie Prefecture". Please check the website link above for more information.' where id = '42nwdMGyuYQxcL-sQuDSW';
update content_bodies set title = '伊勢志摩で真珠文化を発見し学ぶユニークな真珠ジュエリー体験', description = '■アクティビティの詳細■
三重県志摩市は真珠養殖の発祥の地です。豊かな海の資源と受け継がれた技術のおかげで、志摩の真珠は世界でも最高品質のものとして知られています。このプログラムでは、参加者が真珠養殖場を訪れ、職人と話しながら養殖技術を直接学ぶ機会を提供します。また、参加者は牡蠣から真珠を取り出す体験や、非常に珍しい母貝への核入れ作業を行い、真珠養殖のプロセスがどれほど難しいかを学ぶことができます。最後に、参加者は取り出した真珠を使って、世界に一つだけのオリジナルジュエリーを製作します。

■コンテンツの概要＆ストーリー■
真珠養殖の発祥の地である三重県志摩市。豊かな海と技術が受け継がれる志摩で作られる真珠の品質の高さは世界有数です。本プログラムでは、今もなお稼働している真珠養殖の現場に訪問し、伝統的な養殖手法を間近で見学、職人と直接お話することができます。また、「真珠の取り出し体験」や通常は体験することができない「母貝への核入れ作業」を通して、「真珠づくり」の真の難しさを体感してみてください。そして最後に、取り出した真珠で世界に一つだけのオリジナル真珠ジュエリーを製作しましょう。

■特設サイト”Exclusive Activities Information for Travel Agencies”　
＊日本語：https://www.kankomie.or.jp/special/fortravelagencies/
＊English：https://www.kankomie.or.jp/special/fortravelagencies/en/

