「Be.Okinawa」は、沖縄が観光客の皆様をお迎えする気持ちを込めたメッセージです。
「Be.Okinawa」の「Be」とは、「そこにある、存在する」を表し、行動を促す言葉。沖縄を訪れる方々にとって、「美しい自然とあたたかい人たちに囲まれて、本来の自分を取り戻せる島」であることを表しています。

