"Be.Okinawa" is a message that conveys Okinawa''s welcoming spirit to tourists.
The "Be" in "Be.Okinawa" represents "being there, existing," and is a word that encourages action. It signifies that for those visiting Okinawa, it is an island where they can "regain their true selves surrounded by beautiful nature and warm people."

