update content_bodies set title = '名所名宿名物まで美濃路の魅力を余すとこなくお伝えします！', description = 'こちらが今回訪れたところです。
岐阜県の中でも美濃、地図上で言えば下半分を巡りました。

長良川沿いのお宿『鵜匠の家 すぎ山』さんを訪れた日が、新幹線も止まった大雨の日で、いつも川底が透けて見えるほどの清流が魅力のお宿にも関わらず、逆に珍しい濁流の長良川の紹介となってしまっており、大変申し訳なく思っております。
ちなみに鵜飼は通常の雨でしたら決行されます。


