update content_bodies set title = 'We will convey the charm of the Mino Road, from famous sights to local specialties, without missing a thing!', description = 'Here is the place we visited this time.
We traveled through the lower half of Mino in Gifu Prefecture on the map.

The day we visited the riverside inn ''Usyo no Ie Sugiyama'' was a day of heavy rain when even the Shinkansen stopped. Despite being an inn known for its clear stream, where the riverbed is usually visible, we ended up introducing the rare muddy Nagara River instead, and I sincerely apologize for that.
By the way, the cormorant fishing usually takes place even in normal rain.

