update content_bodies set title = 'ESHIKOTOに宿泊し名物名所網羅の福井旅！''AI恐竜動画添え’', description = '皆さまこんにちは。
恐竜博物館に行きたくて計画した今回の旅。
せっかくなので福井名物満載で回ってきました。

どこも予想を遥かに上回る素晴らしさで
大充実の旅となりました。
北陸新幹線福井駅できたので皆様も
ぜひ福井旅行計画されてみてください！

以下、動画登場順に訪れた場所です。

