update content_bodies set title = '【絶景茨城】袋田の滝 氷瀑｜VISIT IBARAKI,JAPAN', description = '日本三大名瀑のひとつに数えられる「袋田の滝」。寒さの厳しい冬には滝全体が真っ白に凍結する姿を見せてくれます。

さらに、大子町の風物詩となった「大子来人～ダイゴライト～」では、自然と光が作り出す神秘の空間が、「袋田の滝」の新たな魅力を発見させてくれます。' where id = 'rzfGZlkP78fZCEyN4hKvW';
update content_bodies set title = '【Breathtaking Ibaraki】Fukuroda Falls Icefall｜VISIT IBARAKI, JAPAN', description = 'Fukuroda Falls, counted among Japan''s three great waterfalls, showcases a completely frozen appearance in the harsh winter cold.

Additionally, the ''Daigo Light'' event, which has become a local tradition in Daigo Town, creates a mystical space formed by nature and light, allowing visitors to discover new charms of ''Fukuroda Falls''.' where id = '7WeCjzzOuvfvyx0k6qPgk';
update content_bodies set title = '【絶景茨城】山桜｜VISIT IBARAKI, JAPAN', description = '茨城県桜川市内の里山には約55万本の山桜が自生しており、淡紅色の桜花ともえぎ色に芽吹く木々が重なり、パッチワークのような風景をみることができます。
磯部桜川公園周辺では約550本の桜を見ることができます。
櫻川磯部稲村神社や公園を含んだ周辺一帯は国の名勝に指定されており、神社及び公園にある桜が国の天然記念物に指定されています。

