update content_bodies set title = '【祝・日本ジオパーク認定／絶景茨城】筑波山 ｜VISIT IBARAKI,JAPAN', description = '昔から「西の富士、東の筑波」と愛称され、朝夕に山肌の色を変えるところから「紫峰」とも呼ばれている筑波山。
男体山と女体山の２つの峰を持ち､古くから信仰の山として栄えてきました。
筑波山への登山道には、道標や土蔵造りの町並みなど、江戸時代の面影を残す歴史の町も楽しむことができ、登山・ハイキイングなど年間を通して自然に親しめるのが魅力です。
また、ケーブルカー、ロープウェイを使えば簡単に山頂にたどり着くことができ､子どもからお年寄りまで､だれもが美しい眺望を楽しむことができます。

筑波山神社
http://www.tsukubasanjinja.jp

