日本が世界に誇る絶景の代表的なものの一つに茨城県ひたちなか市にある国営ひたち海浜公園のネモフィラハーモニーがあります。海から吹く風にその身を揺らせながらネモフィラと空の青が混ざり合い、視界をあざやかな青一色で埋め尽くします。世界にひとつ、ここだけにしかない青の絶景をお楽しみください。

