update content_bodies set title = '[Spectacular Ibaraki] Cherry Blossoms [4K] Hitachi City, Ibaraki Prefecture | VISIT IBARAKI, JAPAN', description = '[Date of filming: 2015.4.6] 
"Kamine Park" in Hitachi City, Ibaraki Prefecture, and "Heiwa Street" in front of Hitachi Station have been selected as one of Japan''s top 100 cherry blossom spots. 
The wind that rushes between the sea and the mountains sways the beautiful cherry blossoms, coloring the lives of the people living in the city, and attracting tourists from both inside and outside Ibaraki Prefecture, bringing vibrancy to the town. 
Every spring, the Hitachi Cherry Blossom Festival is held, and the float "Hitachi Furuibutsu," registered as a UNESCO Intangible Cultural Heritage, adds grandeur to the cherry blossom scenery. 
