update content_bodies set title = '松山城天守閣に行ってきました！', description = 'ここは、愛媛県松山市にある松山城です。松山城には、加藤嘉明の鎧や当時使われていた武器が展示されています。その他にも、武装服を試着できたり、松山城小天守復興の様子のビデオを視聴することもできます。そして、天守閣では360°のパノラマを見ることができます！RyoFさんが松山城入口までの景色を撮影しております！→https://youtu.be/T1l3eHh-TaQ' where id = 'ZyLPc86565TPrRt0rGI_v';
update content_bodies set title = 'I visited Matsuyama Castle''s Main Keep!', description = 'This is Matsuyama Castle located in Matsuyama City, Ehime Prefecture. Matsuyama Castle displays armor worn by Kato Yoshiaki and weapons used at that time. Additionally, you can try on armored clothing and watch a video of the restoration of the Matsuyama Castle''s small keep. Moreover, you can enjoy a 360° panorama from the main keep! RyoF has captured the scenery leading to the entrance of Matsuyama Castle! → https://youtu.be/T1l3eHh-TaQ' where id = 'TxFWoGahanKa6ofC1PuvN';
update content_bodies set title = '今治城に行ってきました！(天守閣編)', description = 'ここは、愛媛県今治市にある今治城です！今回は、天守閣を撮影しており！詳しい情報はこちら！→http://museum.city.imabari.ehime.jp/imabarijo/ 本丸跡編→https://youtu.be/7DIJ32CeSvI' where id = '4lxZTzF_heuKHujk66owv';
update content_bodies set title = 'I visited Imabari Castle! (Tenshukaku Edition)', description = 'This is Imabari Castle located in Imabari City, Ehime Prefecture! This time, I was filming the tenshukaku! For more detailed information, click here! → http://museum.city.imabari.ehime.jp/imabarijo/ Main Keep Ruins Edition → https://youtu.be/7DIJ32CeSvI' where id = 'Rc-5O-mtas7HnZYhXxdfq';
update content_bodies set title = '高知城に行ってきました！', description = 'ここは、高知県高知市丸ノ内１丁目２−２−１にある高知城です。 詳しい情報はこちら！→http://kochipark.jp/kochijyo/ そしてこの動画の最後には、高知県高知市の日曜市を撮影しております。 日曜市についての詳しい情報はこちら！→http://www.city.kochi.kochi.jp/soshiki/39/nichiyouichi.html' where id = 'aP5XTw8AlAgHKMslmk4xs';
update content_bodies set title = 'I visited Kochi Castle!', description = 'This is Kochi Castle located at 1-2-2-1 Marunouchi, Kochi City, Kochi Prefecture. For more information, click here! → http://kochipark.jp/kochijyo/ And at the end of this video, I have filmed the Sunday Market in Kochi City, Kochi Prefecture. For more information about the Sunday Market, click here! → http://www.city.kochi.kochi.jp/soshiki/39/nichiyouichi.html' where id = 'fvQMsMJw_ivWbn8JYDwBb';
update content_bodies set title = '大洲城に行ってきました！', description = 'ここは、愛媛県大洲市大洲９０３にある大洲城です。大洲城には、2004年に復元された天守をはじめ、国指定重要文化財に選定された4棟の櫓があります。そしてこの動画の最後には、愛媛県松山市を流れる宮前川にいたコガモを撮影しております。' where id = 'UgazhgtL0BqFmXqwD2l_G';
update content_bodies set title = 'I visited Ozu Castle!', description = 'This is Ozu Castle, located at 903 Ozu, Ozu City, Ehime Prefecture. Ozu Castle features the main keep, which was restored in 2004, as well as four turrets designated as Important Cultural Properties by the national government. At the end of this video, we also captured footage of a female teal that was in the Miyamae River flowing through Matsuyama City, Ehime Prefecture.' where id = 'dZE2A0AHXnTS0M5tWJveI';
update content_bodies set title = '宇和島城に行ってきました！(天守編)', description = 'ここは、愛媛県宇和島市にある宇和島城です。宇和島城は、標高80mの丘上に築かれた平山城です。伊達氏2代宗利が大改修し現在の形になってます。天守閣は国指定重要文化財です。そしてこの動画の最後には、愛媛県宇和島市にいた猫を撮影しております。 登城編→https://youtu.be/bJbAEg2EYcE

#宇和島城 #愛媛県宇和島市 #伊達藩' where id = 'SPWxCvCRbU8zbx4wFK02G';
update content_bodies set title = 'I visited Uwajima Castle! (Main Keep Edition)', description = 'This is Uwajima Castle located in Uwajima City, Ehime Prefecture. Uwajima Castle is a flatland castle built on a hill at an elevation of 80m. It was significantly renovated by the second generation of the Date clan, Muneyoshi, to take its current form. The main keep is a nationally designated important cultural property. At the end of this video, I have captured a cat that was in Uwajima City, Ehime Prefecture. Castle Climbing Edition → https://youtu.be/bJbAEg2EYcE

#UwajimaCastle #UwajimaCityEhimePrefecture #DateDomain' where id = 'GspYfuJ4n3G1qBBcwJ3hQ';
update content_bodies set title = '審査員特別賞「立ち上がろう雲仙市」un film de Ryuji Shibata', description = '第17回NCCふるさとCM大賞　受賞作品
ふるさと長崎の30秒動画を募集しました。
協賛：十八親和銀行　

#NCCふるさとCM大賞 #長崎文化放送' where id = 'vmluTWsvDH2DHh0-HfT9C';
