We solicited 30-second videos about our hometown Nagasaki.
Sponsored by: Juhachi Shinnwa Bank

#NCC Hometown CM Award #Nagasaki Cultural Broadcasting' where id = 'aypHCo9IjSNkHymNGqddx';
